<?php

declare(strict_types=1);

namespace OpenTelemetry\Contrib\Ci\Tests;

use OpenTelemetry\Contrib\Ci\Project;
use OpenTelemetry\Contrib\Ci\Workflows;
use PHPUnit\Framework\TestCase;

/**
 * The workflow generated for each project, and the problems --check
 * reports when the files on disk don't match.
 */
final class WorkflowsTest extends TestCase
{
    public function test_names_each_workflow_after_its_project(): void
    {
        $this->assertSame(
            ['.github/workflows/project-aws.yml', '.github/workflows/project-instrumentation-httpasyncclient.yml'],
            array_keys(Workflows::generate(self::projects('Instrumentation/HttpAsyncClient', 'Aws'))),
        );
    }

    public function test_writes_a_workflow_that_calls_php_project_for_its_project(): void
    {
        $this->assertSame(<<<'YAML'
            # Generated by .github/ci/matrix.php --generate. Do not edit.
            # See .github/ci/README.md.
            name: Instrumentation/MySqli

            on:
              push:
                branches: [ main ]
                paths:
                  - 'src/Instrumentation/MySqli/**'
                  - '.github/workflows/project-instrumentation-mysqli.yml'
                  - '.github/workflows/php-project.yml'
                  - '.github/ci/matrix.php'
                  - '.github/ci/composer.json'
                  - '.github/ci/src/**'
              pull_request:
                branches: [ main ]
                paths:
                  - 'src/Instrumentation/MySqli/**'
                  - '.github/workflows/project-instrumentation-mysqli.yml'
                  - '.github/workflows/php-project.yml'
                  - '.github/ci/matrix.php'
                  - '.github/ci/composer.json'
                  - '.github/ci/src/**'
              schedule:
                - cron: '17 4 * * 1' # weekly, against new dependency releases
              workflow_dispatch:

            permissions:
              contents: read

            # Only pull requests cancel. A newer push to main may not touch this
            # project, and then nothing would test the cancelled commit.
            concurrency:
              group: ${{ github.workflow }}-${{ github.event.pull_request.number || github.run_id }}
              cancel-in-progress: true

            jobs:
              php:
                name: CI
                uses: ./.github/workflows/php-project.yml # zizmor: ignore[self-repository] actionlint doesn't support $/ yet
                with:
                  project: Instrumentation/MySqli
                secrets:
                  CODECOV_TOKEN: ${{ secrets.CODECOV_TOKEN }}

            YAML, Workflows::generate(self::projects('Instrumentation/MySqli'))['.github/workflows/project-instrumentation-mysqli.yml']);
    }

    public function test_runs_a_project_with_services_when_its_services_change(): void
    {
        $project = Project::fromComposerJson('Instrumentation/PDO', '{"extra": {"ci": {"services": ["mysql", "rabbitmq"]}}}', true);
        $paths = <<<'YAML'
                  - '.github/ci/src/**'
                  - 'docker-compose.yaml'
                  - 'docker/mysql/**'
                  - 'docker/rabbitmq/**'

            YAML;

        $this->assertSame(2, substr_count(Workflows::generate([$project])['.github/workflows/project-instrumentation-pdo.yml'], $paths));
    }

    public function test_accepts_current_workflows(): void
    {
        $projects = self::projects('Aws', 'Symfony');

        $this->assertSame([], Workflows::problems($projects, Workflows::generate($projects)));
    }

    public function test_reports_a_missing_workflow(): void
    {
        $this->assertSame(
            ['::error file=.github/workflows/project-symfony.yml::src/Symfony has no workflow. Run make ci-generate.'],
            Workflows::problems(self::projects('Aws', 'Symfony'), Workflows::generate(self::projects('Aws'))),
        );
    }

    public function test_reports_an_edited_workflow(): void
    {
        $projects = self::projects('Aws');
        $workflows = Workflows::generate($projects);
        $workflows['.github/workflows/project-aws.yml'] .= "# edited\n";

        $this->assertSame(
            ['::error file=.github/workflows/project-aws.yml::.github/workflows/project-aws.yml differs from what matrix.php generates. Run make ci-generate.'],
            Workflows::problems($projects, $workflows),
        );
    }

    public function test_reports_a_workflow_with_no_project(): void
    {
        $this->assertSame(
            ['::error file=.github/workflows/project-gone.yml::.github/workflows/project-gone.yml has no project. Run make ci-generate.'],
            Workflows::problems([], ['.github/workflows/project-gone.yml' => '']),
        );
    }

    public function test_reports_projects_that_would_share_a_workflow(): void
    {
        $projects = self::projects('Foo/Bar', 'Foo-Bar');

        $this->assertSame(
            ['::error file=src/Foo-Bar/composer.json::src/Foo-Bar and src/Foo/Bar would share the workflow .github/workflows/project-foo-bar.yml. Rename one.'],
            Workflows::problems($projects, Workflows::generate($projects)),
        );
    }

    /** @return list<Project> */
    private static function projects(string ...$names): array
    {
        return array_map(fn (string $name) => Project::fromComposerJson($name, '{}', true), array_values($names));
    }
}
